package org.aegis.android;

import android.content.Context;
import android.os.SystemClock;
import com.google.gson.*;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.*;
import java.util.concurrent.Semaphore;
import org.securemail.client.community.CommunityJson;
import org.securemail.client.ecosystemauth.IdentityClient600;
import org.securemail.client.net.TorTransport;
import org.securemail.ecosystem.protocol.IdentityProtocol;
import org.securemail.protocol.Limits;

/** Real signed Identity RPC through existing onion-only SOCKS transport, with no account private key. */
final class CoreIdentity {
    private static CoreIdentity instance;
    static synchronized CoreIdentity get(Context c){if(!AndroidPolicy.CORE.equals(c.getPackageName()))throw new SecurityException("Координатор доступен только АЕГИС");if(instance==null)instance=new CoreIdentity(c.getApplicationContext());return instance;}
    private final Context context;private final PrivateVault vault;private final Semaphore operations=new Semaphore(1);private final Map<String,Proposal> pending=new HashMap<>();
    private volatile boolean nativeTor;private int clientSocks;private IdentityClient600 client;private Config config;private volatile String status="Identity не настроен";
    private CoreIdentity(Context c){context=c;vault=new PrivateVault(c);try{byte[] b=vault.get("core-public-config");if(b!=null)try{JsonObject j=CommunityJson.parse(b);config=new Config(text(j,"onion"),integer(j,"port"),integer(j,"socksPort"),text(j,"serverKey"));nativeTor=j.has("nativeTor")&&j.get("nativeTor").getAsBoolean();}finally{Arrays.fill(b,(byte)0);}}catch(Exception damaged){status="Публичные параметры Identity повреждены; сеть отключена";}}
    static final class Config {
        final String onion,key;final int port,socks;final byte[] server;
        Config(String onion,int port,int socks,String key){this.onion=Limits.onion(onion);if(port<1||port>65535||socks<1||socks>65535)throw new IllegalArgumentException("Неверный порт");this.port=port;this.socks=socks;server=IdentityProtocol.unb64(key,44);IdentityProtocol.publicKey(server);this.key=IdentityProtocol.b64(server);}
        JsonObject json(){JsonObject j=new JsonObject();j.addProperty("onion",onion);j.addProperty("port",port);j.addProperty("socksPort",socks);j.addProperty("serverKey",key);return j;}
    }
    synchronized void configure(String onion,int port,int socks,String key)throws Exception {Config c=new Config(onion,port,socks,key);try{String old=SessionLedger.get(context).publicPin();if(!old.equals(c.key))throw new SecurityException("Нельзя заменить закреплённый ключ Identity");}catch(SecurityException missing){if(!"Серверный ключ не задан".equals(missing.getMessage()))throw missing;}JsonObject configuration=c.json();configuration.addProperty("nativeTor",true);byte[] data=configuration.toString().getBytes(StandardCharsets.UTF_8);try{vault.put("core-public-config",data);}finally{Arrays.fill(data,(byte)0);}if(client!=null)client.close();client=null;config=c;nativeTor=true;pending.clear();status="Параметры сохранены. Встроенный Tor запускается при сетевом входе; внешнего fallback нет";}
    synchronized void nativeTor(boolean enabled)throws Exception {Config c=configured();JsonObject j=c.json();j.addProperty("nativeTor",enabled);byte[] b=j.toString().getBytes(StandardCharsets.UTF_8);try{vault.put("core-public-config",b);}finally{Arrays.fill(b,(byte)0);}if(client!=null)client.close();client=null;nativeTor=enabled;status=enabled?"Выбран встроенный Tor; прямого fallback нет":"Явно выбран внешний loopback Tor SOCKS";}
    JsonObject publicConfig(String pkg)throws java.io.IOException {JsonObject j;boolean own;synchronized(this){j=publicConfig();own=nativeTor;}if(own)j.addProperty("socksPort",CoreTor.get(context).socks(pkg));j.addProperty("nativeTor",own);return j;}
    synchronized JsonObject publicConfig(){if(config==null)throw new SecurityException("Identity не настроен");return config.json();}
    synchronized String status(){return status;}
    private synchronized Config configured(){if(config==null)throw new SecurityException("Укажите onion и проверенный ключ Identity");return config;}
    private IdentityClient600 transport()throws java.io.IOException {Config c;boolean own;synchronized(this){c=configured();own=nativeTor;}int socks=own?CoreTor.get(context).awaitSocks(AndroidPolicy.CORE):c.socks;synchronized(this){if(config!=c||nativeTor!=own)throw new java.io.IOException("Настройки транспорта изменены");if(client==null||clientSocks!=socks){if(client!=null)client.close();client=new IdentityClient600(c.onion,c.port,c.server,new TorTransport("127.0.0.1",socks));clientSocks=socks;}return client;}}
    JsonObject challengeDevice(String account)throws Exception {if(!operations.tryAcquire())throw new SecurityException("Проверка Identity уже выполняется");try{IdentityProtocol.idValue(account);Config c=configured();byte[] device=vault.devicePublicKey();String nonce=IdentityProtocol.nonce();long now=System.currentTimeMillis();JsonObject d=new JsonObject();d.addProperty("accountId",account);d.addProperty("deviceKey",IdentityProtocol.b64(device));d.addProperty("time",now);d.addProperty("nonce",nonce);d.addProperty("proof",IdentityProtocol.b64(vault.deviceProof(IdentityProtocol.login(IdentityProtocol.id(c.server),account,IdentityProtocol.id(device),now,nonce))));JsonObject result=transport().rpc("challengeDevice",d);if(!account.equals(text(result,"accountId"))||!IdentityProtocol.b64(device).equals(text(result,"deviceKey")))throw new SecurityException("Identity вернул другое устройство");IdentityProtocol.nonceValue(text(result,"challenge"));status="Заявка устройства получена. Нужна проверка на уже доверенном устройстве";return result;}finally{operations.release();}}
    void login(String account)throws Exception {if(!operations.tryAcquire())throw new SecurityException("Проверка Identity уже выполняется");try{IdentityProtocol.idValue(account);SessionLedger.get(context).requireSameAccount(account);Config c=configured();byte[] device=vault.devicePublicKey();String deviceId=IdentityProtocol.id(device),nonce=IdentityProtocol.nonce();long now=System.currentTimeMillis();JsonObject d=new JsonObject();d.addProperty("accountId",account);d.addProperty("deviceId",deviceId);d.addProperty("time",now);d.addProperty("nonce",nonce);d.addProperty("proof",IdentityProtocol.b64(vault.deviceProof(IdentityProtocol.login(IdentityProtocol.id(c.server),account,deviceId,now,nonce))));JsonObject s=transport().rpc("login",d);long generation=number(s,"generation");if(!account.equals(text(s,"accountId"))||!deviceId.equals(text(s,"deviceId"))||generation<1||number(s,"expiresAt")<=System.currentTimeMillis())throw new SecurityException("Ответ входа не соответствует устройству");SessionLedger.get(context).lock();CoreBrokerService.revoked();Proposal core=new Proposal(AndroidPolicy.CORE,account,deviceId,generation,vault.appPublicKey(),EnumSet.of(IdentityProtocol.Scope.ACCOUNT_READ),IdentityProtocol.id(c.server));String wire=issue(core,vault.prove(core.bytes));SessionLedger.get(context).install(c.key,wire);synchronized(this){pending.clear();}status="Вход подтверждён подписанным ответом Identity через настроенный Tor SOCKS";CoreBrokerService.revoked();}finally{operations.release();}}
    private static Set<IdentityProtocol.Scope> scopes(String pkg){switch(AndroidPolicy.app(pkg)){case MAIL:return EnumSet.of(IdentityProtocol.Scope.MAIL_READ,IdentityProtocol.Scope.MAIL_SEND,IdentityProtocol.Scope.CONTACTS_READ);case GLAS:return EnumSet.of(IdentityProtocol.Scope.VOICE_CALL,IdentityProtocol.Scope.CONTACTS_READ);case STRAZH:return EnumSet.of(IdentityProtocol.Scope.THREAT_SCAN);default:throw new SecurityException("Делегирование этому приложению запрещено");}}
    private static final class Proposal {
        final String pkg,account,device,nonce,audience;final IdentityProtocol.App app;final long generation,time,ttl=3_600_000L,until=SystemClock.elapsedRealtime()+30_000;final byte[] key,bytes;final Set<IdentityProtocol.Scope> scopes;
        Proposal(String pkg,String account,String device,long generation,byte[] key,Set<IdentityProtocol.Scope> scopes,String audience){this(pkg,AndroidPolicy.app(pkg),account,device,generation,key,scopes,audience);}
        Proposal(String pkg,IdentityProtocol.App app,String account,String device,long generation,byte[] key,Set<IdentityProtocol.Scope> scopes,String audience){this.app=app;this.pkg=pkg;this.account=account;this.device=device;this.generation=generation;this.key=key.clone();this.scopes=Collections.unmodifiableSet(EnumSet.copyOf(scopes));this.audience=audience;nonce=IdentityProtocol.nonce();time=System.currentTimeMillis();bytes=IdentityProtocol.capabilityRequest(audience,account,device,generation,app,key,scopes,ttl,time,nonce);}
        JsonObject json(){JsonObject j=new JsonObject();j.addProperty("accountId",account);j.addProperty("deviceId",device);j.addProperty("generation",generation);j.addProperty("appId",app.name());j.addProperty("proofKey",IdentityProtocol.b64(key));JsonArray list=new JsonArray();for(IdentityProtocol.Scope s:scopes)list.add(s.name());j.add("capabilities",list);j.addProperty("ttl",ttl);j.addProperty("time",time);j.addProperty("nonce",nonce);j.addProperty("audience",audience);return j;}
    }
    synchronized String propose(String pkg,byte[] key)throws Exception {IdentityProtocol.Capability core=IdentityProtocol.decodeCapability(SessionLedger.get(context).coreToken());if(!IdentityProtocol.id(vault.devicePublicKey()).equals(core.deviceId))throw new SecurityException("Нужен сетевой вход с ключом этого устройства");Proposal p=new Proposal(pkg,core.accountId,core.deviceId,core.generation,key,scopes(pkg),core.audience);pending.put(pkg,p);return p.json().toString();}
    String consent(String pkg,byte[] key,String proposalId,byte[] signature)throws Exception {if(!operations.tryAcquire())throw new SecurityException("Identity занят");try{Proposal p;synchronized(this){p=pending.remove(pkg);}if(p==null||!p.nonce.equals(proposalId)||SystemClock.elapsedRealtime()>=p.until||!MessageDigest.isEqual(key,p.key)||!IdentityProtocol.verify(key,p.bytes,signature))throw new SecurityException("Подтверждение приложения не соответствует предложению");IdentityProtocol.Capability current=IdentityProtocol.decodeCapability(SessionLedger.get(context).coreToken());if(current.generation!=p.generation||!current.accountId.equals(p.account))throw new SecurityException("Сессия отозвана");String wire=issue(p,signature);SessionLedger.get(context).addCapability(pkg,wire);return wire;}finally{operations.release();}}
    private String issue(Proposal p,byte[] appProof)throws Exception {JsonObject d=p.json();d.remove("audience");d.addProperty("deviceProof",IdentityProtocol.b64(vault.deviceProof(p.bytes)));d.addProperty("appProof",IdentityProtocol.b64(appProof));JsonObject result=transport().rpc("issueCapability",d);String wire=text(result,"capability");IdentityProtocol.Capability cap=IdentityProtocol.decodeCapability(wire);Config c=configured();if(!IdentityProtocol.verifyCapability(cap,c.server,System.currentTimeMillis())||!cap.accountId.equals(p.account)||!cap.deviceId.equals(p.device)||cap.generation!=p.generation||cap.appId!=p.app||!cap.capabilities.equals(p.scopes)||!MessageDigest.isEqual(cap.proofKey,p.key))throw new SecurityException("Выдан другой допуск");return wire;}
    void issueNetworkGrant()throws Exception{if(!operations.tryAcquire())throw new SecurityException("Identity занят");try{IdentityProtocol.Capability core=IdentityProtocol.decodeCapability(SessionLedger.get(context).coreToken());if(!IdentityProtocol.id(vault.devicePublicKey()).equals(core.deviceId))throw new SecurityException("Нужен сетевой вход этого устройства");Proposal p=new Proposal(AndroidPolicy.CORE,IdentityProtocol.App.NETWORK,core.accountId,core.deviceId,core.generation,vault.networkPublicKey(),EnumSet.of(IdentityProtocol.Scope.NETWORK_CONTROL),core.audience);String wire=issue(p,vault.networkProof(p.bytes));IdentityProtocol.Capability current=IdentityProtocol.decodeCapability(SessionLedger.get(context).coreToken());if(current.generation!=core.generation||!current.accountId.equals(core.accountId))throw new SecurityException("Поколение отозвано");vault.put("network-grant",wire.getBytes(StandardCharsets.US_ASCII));}finally{operations.release();}}
    boolean networkActive(){try{IdentityProtocol.Capability core=IdentityProtocol.decodeCapability(SessionLedger.get(context).coreToken());byte[] saved=vault.get("network-grant");if(saved==null)return false;IdentityProtocol.Capability network;try{network=IdentityProtocol.decodeCapability(new String(saved,StandardCharsets.US_ASCII));}finally{Arrays.fill(saved,(byte)0);}return IdentityProtocol.verifyCapability(network,configured().server,System.currentTimeMillis())&&network.appId==IdentityProtocol.App.NETWORK&&network.capabilities.equals(EnumSet.of(IdentityProtocol.Scope.NETWORK_CONTROL))&&MessageDigest.isEqual(network.proofKey,vault.networkPublicKey())&&network.accountId.equals(core.accountId)&&network.deviceId.equals(core.deviceId)&&network.generation==core.generation&&network.offlineUntil>System.currentTimeMillis();}catch(Exception denied){return false;}}
    void recheck(){if(!operations.tryAcquire())return;boolean revoked=false;try{if(!SessionLedger.get(context).active())return;String token=SessionLedger.get(context).coreToken();if(!transport().isActive(token)){revoked=true;try{SessionLedger.get(context).logout();}finally{status="Сервер отозвал поколение сессии";CoreBrokerService.exited();}}else status="Действительность сессии подтверждена Identity";}catch(Exception unavailable){if(!revoked)status="Сетевая сверка недоступна; разрешены только действующие автономные допуски";}finally{operations.release();}}
    void revokeRemote()throws Exception {if(!operations.tryAcquire())throw new SecurityException("Дождитесь завершения запроса Identity");try{IdentityProtocol.Capability current=IdentityProtocol.decodeCapability(SessionLedger.get(context).tokenForLogout());Proposal control=new Proposal(AndroidPolicy.CORE,current.accountId,current.deviceId,current.generation,vault.appPublicKey(),EnumSet.of(IdentityProtocol.Scope.SESSION_MANAGE),current.audience);String wire=issue(control,vault.prove(control.bytes));IdentityProtocol.Capability cap=IdentityProtocol.decodeCapability(wire);long now=System.currentTimeMillis();String nonce=IdentityProtocol.nonce();JsonObject d=new JsonObject();d.addProperty("capability",wire);d.addProperty("time",now);d.addProperty("nonce",nonce);d.addProperty("proof",IdentityProtocol.b64(vault.prove(IdentityProtocol.request(cap,"session.manage",new byte[0],now,nonce))));JsonObject result=transport().rpc("revoke",d);if(!result.has("revoked")||!result.get("revoked").isJsonPrimitive()||!result.getAsJsonPrimitive("revoked").isBoolean()||!result.get("revoked").getAsBoolean())throw new SecurityException("Серверный выход не подтверждён");status="Сервер подтвердил отзыв сессии";}finally{operations.release();}}
    synchronized void closeNetwork(){if(client!=null)client.close();client=null;pending.clear();}
    private static String text(JsonObject j,String name){JsonElement e=j.get(name);if(e==null||!e.isJsonPrimitive()||!e.getAsJsonPrimitive().isString()||e.getAsString().length()>4096)throw new SecurityException("Неверный ответ Identity");return e.getAsString();}
    private static long number(JsonObject j,String name){JsonElement e=j.get(name);if(e==null||!e.isJsonPrimitive()||!e.getAsJsonPrimitive().isNumber()||!e.getAsString().matches("[0-9]{1,19}"))throw new SecurityException("Неверное число Identity");return Long.parseLong(e.getAsString());}
    private static int integer(JsonObject j,String name){long n=number(j,name);if(n>65535)throw new SecurityException("Порт Identity");return (int)n;}
}
